def main():
 checks=[]; hashes={}
 for cid,rows in sorted(R.items()):
  assert len(rows)==10
  path=P/'inputs'/f'b{cid}.json';raw=path.read_bytes();d=json.loads(raw)
  hashes[path.name]=hashlib.sha256(raw).hexdigest()
  for i,(expr,display,unit) in enumerate(rows,1):
   result=eval(expr,{'__builtins__':{}},{'sqrt':math.sqrt,'pi':math.pi,'log':math.log,'log10':math.log10,'exp':math.exp,'sin':math.sin,'cos':math.cos,'ceil':math.ceil,'max':max,'min':min})
   assert math.isclose(result,display,rel_tol=.003,abs_tol=1e-9),(cid,i,result,display)
   checks.append(dict(course=f'b{cid}',unit=i,expression=expr,result=result,displayed=display,outputUnit=unit,status='pass'))
 report=dict(date='2026-10-21',reviewer='Author independent arithmetic expression check',scope='One primary numeric result per unit; dimensions and physical boundaries reread. This is educational verification, not project design certification.',models=len(checks),checks=checks,inputSha256=hashes)
 (P/'audit_rivers.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
 print(f'{len(checks)} numeric models PASS across {len(R)} courses')
if __name__=='__main__':main()
